/// Round-trips a settings object through the type for `id`.
///
/// The dispatch behind [`super::validate_settings`], which is where the reasoning is.
pub(crate) fn check_settings(id: ModId, value: Value) -> Result<Value, Error> {
    match id {
        ModId::Fps => super::check::<FpsSettings>(id, value),
        ModId::Keystrokes => super::check::<KeystrokesSettings>(id, value),
        ModId::Cps => super::check::<CpsSettings>(id, value),
        ModId::Ping => super::check::<PingSettings>(id, value),
        ModId::Coordinates => super::check::<CoordinatesSettings>(id, value),
        ModId::ArmorStatus => super::check::<ArmorStatusSettings>(id, value),
        ModId::PotionEffects => super::check::<PotionEffectsSettings>(id, value),
        ModId::Watermark => super::check::<WatermarkSettings>(id, value),
        ModId::ToggleSprint => super::check::<ToggleSprintSettings>(id, value),
        ModId::Fullbright => super::check::<FullbrightSettings>(id, value),
        ModId::Hitboxes => super::check::<HitboxesSettings>(id, value),
        ModId::Zoom => super::check::<ZoomSettings>(id, value),
        ModId::Crosshair => super::check::<CrosshairSettings>(id, value),
        ModId::Direction => super::check::<DirectionSettings>(id, value),
        ModId::Combo => super::check::<ComboSettings>(id, value),
        ModId::Saturation => super::check::<SaturationSettings>(id, value),
        ModId::Momentum => super::check::<MomentumSettings>(id, value),
        ModId::Memory => super::check::<MemorySettings>(id, value),
        ModId::ServerAddress => super::check::<ServerAddressSettings>(id, value),
        ModId::ItemCounter => super::check::<ItemCounterSettings>(id, value),
        ModId::Stopwatch => super::check::<StopwatchSettings>(id, value),
        ModId::Fov => super::check::<FovSettings>(id, value),
        ModId::ToggleSneak => super::check::<ToggleSneakSettings>(id, value),
        ModId::Overlay => super::check::<OverlaySettings>(id, value),
    }
}

